async (page) => {
  const { execSync } = require('child_process');
  // Find all symlinks under /workspace and check if broken
  try {
    const out = execSync("find /workspace -type l 2>/dev/null", { encoding: 'utf8' });
    const links = out.split('\n').filter(Boolean);
    const broken = [];
    const fs = require('fs');
    for (const l of links) {
      try {
        fs.statSync(l); // follows symlink
      } catch (e) {
        broken.push(l);
      }
    }
    return { total: links.length, broken };
  } catch (e) {
    return { error: e.message };
  }
}

